CREATE INDEX idx_fullend_cache_expires ON fullend_cache (expires_at);


CREATE TABLE fullend_queue (
    id BIGINT NOT NULL GENERATED ALWAYS AS IDENTITY,
    topic TEXT NOT NULL,
